import{c as a,Q as s,j as l,m as o}from"./chunks/framework.DOi4mjdC.js";const g=JSON.parse('{"title":"性能调优","description":"","frontmatter":{},"headers":[{"level":1,"title":"性能调优","slug":"性能调优"},{"level":2,"title":"性能采集与分析工具","slug":"性能采集与分析工具"},{"level":2,"title":"NPU域上板性能分析","slug":"npu域上板性能分析"},{"level":2,"title":"NPU域仿真性能分析","slug":"npu域仿真性能分析"}],"relativePath":"guide/编程指南/调试调优/性能调优.md","filePath":"guide/编程指南/调试调优/性能调优.md"}'),n={name:"guide/编程指南/调试调优/性能调优.md"};function p(e,t,i,r,d,u){return s(),l("div",null,[...t[0]||(t[0]=[o(`<h1 id="性能调优" tabindex="-1">性能调优 <a class="header-anchor" href="#性能调优" aria-label="Permalink to &quot;性能调优&quot;">​</a></h1><h2 id="性能采集与分析工具" tabindex="-1">性能采集与分析工具 <a class="header-anchor" href="#性能采集与分析工具" aria-label="Permalink to &quot;性能采集与分析工具&quot;">​</a></h2><p>通过毕昇编译器编译生成可执行程序后，使用msProf工具采集Ascend C算子在AI处理器上执行的性能数据，进行性能精细调优。</p><p><a href="https://hiascend.com/document/redirect/CannCommercialToolOpDev" target="_blank" rel="noreferrer">msProf工具</a>包含msprof op和msprof op simulator两种使用方式，协助用户定位算子内存、算子代码以及算子指令的异常，实现全方位的算子调优。两种使用方式的详细说明请参考表1。</p><p><strong>表1 msprof op和msprof op simulator功能说明表</strong></p><table tabindex="0"><thead><tr><th>功能名称</th><th>适用场景</th><th>使用方式</th><th>展示的图形</th></tr></thead><tbody><tr><td>msprof op</td><td>适用于上板性能分析（实际运行环境中的性能分析），可协助用户定位算子内存和性能瓶颈。</td><td>直接分析运行中的算子，无需额外配置，适合在板环境中快速定位算子性能问题。</td><td>计算内存热力图&lt;br/&gt;Roofline瓶颈分析图&lt;br/&gt;Cache热力图&lt;br/&gt;通算流水图&lt;br/&gt;算子代码热点图</td></tr><tr><td>msprof op simulator</td><td>适用于仿真性能分析，可协助用户分析算子指令和代码热点问题。</td><td>需要参考msprof op simulator配置，配置环境变量（如LD_LIBRARY_PATH）和编译选项（如添加-g生成调试信息），适合在仿真环境中详细分析算子行为。</td><td>指令流水图&lt;br/&gt;算子代码热点图&lt;br/&gt;内存通路吞吐率波形图</td></tr></tbody></table><h2 id="npu域上板性能分析" tabindex="-1">NPU域上板性能分析 <a class="header-anchor" href="#npu域上板性能分析" aria-label="Permalink to &quot;NPU域上板性能分析&quot;">​</a></h2><p>算子程序通过毕昇编译器编译生成可执行程序后，可以通过msprof op在NPU上完成性能采集。以SIMD编程场景为例，使用msprof工具采集上板性能数据大致步骤如下：</p><ol><li><p>参考<a href="./../编译与运行/AI-Core-SIMD编译/算子编译简介.html">AI Core SIMD编译</a>，编译add算子样例，生成可执行文件。</p><p>dav-后为NPU架构版本号，请根据实际情况进行替换，各产品型号对应的架构版本号请通过<a href="./../语言扩展层/SIMD-BuiltIn关键字.html#table65291052154114">对应关系表</a>进行查询。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>bisheng add_custom.asc -o add_custom --npu-arch=dav-2201</span></span></code></pre></div></li><li><p>使用msprof op调用算子可执行文件进行性能采集。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>msprof op ./add_custom</span></span></code></pre></div></li><li><p>查看性能数据，了解当前算子性能瓶颈。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>性能数据文件夹结构示例：</span></span>
<span class="line"><span>OPPROF_{timestamp}_XXX</span></span>
<span class="line"><span>├──dump                       # 原始的性能数据，用户无需关注</span></span>
<span class="line"><span>├──ArithmeticUtilization.csv  # cube/vector指令cycle占比，建议优化算子逻辑，减少冗余计算指令</span></span>
<span class="line"><span>├──L2Cache.csv                # L2 Cache命中率，影响MTE2，建议合理规划数据搬运逻辑，增加命中率</span></span>
<span class="line"><span>├──Memory.csv                 # UB，L1和主存储器读写带宽速率，单位GB/s</span></span>
<span class="line"><span>├──MemoryL0.csv               # L0A，L0B，和L0C读写带宽速率，单位GB/s</span></span>
<span class="line"><span>├──MemoryUB.csv               # Vector和Scalar到UB的读写带宽速率，单位GB/s</span></span>
<span class="line"><span>├──OpBasicInfo.csv            # 算子基础信息</span></span>
<span class="line"><span>├──PipeUtilization.csv        # pipe类指令耗时和占比，建议优化数据搬运逻辑，提高带宽利用率</span></span>
<span class="line"><span>├──ResourceConflictRatio.csv  # UB上的bank group、bank conflict和资源冲突率在所有指令中的占比， 建议减少/避免对于同一个bank读写冲突或bank group的读读冲突</span></span>
<span class="line"><span>└──visualize_data.bin         # MindStudio Insight呈现文件</span></span></code></pre></div></li></ol><p><strong>表2 msprof op文件介绍</strong></p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;24.54%&quot;&gt;&lt;p&gt;名称&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;75.46000000000001%&quot;&gt;&lt;p&gt;说明&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;24.54%&quot;&gt;&lt;p&gt;dump文件夹&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;75.46000000000001%&quot;&gt;&lt;p&gt;原始的性能数据，用户无需关注。 &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;24.54%&quot;&gt;&lt;p&gt;ArithmeticUtilization.csv&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;75.46000000000001%&quot;&gt;&lt;p&gt;Cube和Vector类型的指令耗时和占比，可参考ArithmeticUtilization（Cube及Vector类型指令耗时和占比）。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;24.54%&quot;&gt;&lt;p&gt;L2Cache.csv&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;75.46000000000001%&quot;&gt;&lt;p&gt;L2 Cache命中率，可参考L2Cache（L2 Cache命中率）。 &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;24.54%&quot;&gt;&lt;p&gt;Memory.csv&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;75.46000000000001%&quot;&gt;&lt;p&gt;UB/L1/L2/主存储器采集内存读写带宽速率，可参考Memory（内存读写带宽速率）。 &lt;/td&gt; &lt;/tr&gt;</p><p>&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;24.54%&quot;&gt;&lt;p&gt;MemoryL0.csv&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;75.46000000000001%&quot;&gt;&lt;p&gt;L0A/L0B/L0C采集内存读写带宽速率，可参考MemoryL0（L0读写带宽速率）。 &lt;/td&gt; &lt;/tr&gt;</p><p>&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;24.54%&quot;&gt;&lt;p&gt;MemoryUB.csv&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;75.46000000000001%&quot;&gt;&lt;p&gt;mte/vector/scalar采集ub读写带宽速率，可参考MemoryUB（UB读写带宽速率）。 &lt;/td&gt; &lt;/tr&gt;</p><p>&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;24.54%&quot;&gt;&lt;p&gt;PipeUtilization.csv&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;75.46000000000001%&quot;&gt;&lt;p&gt;采集计算单元和搬运单元耗时和占比，可参考PipeUtilization（计算单元和搬运单元耗时占比）。 &lt;/td&gt; &lt;/tr&gt;</p><p>&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;24.54%&quot;&gt;&lt;p&gt;ResourceConflictRatio.csv&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;75.46000000000001%&quot;&gt;&lt;p&gt;UB上的bank group、bank conflict和资源冲突在所有指令中的占比，可参考ResourceConflictRatio（资源冲突占比）。 &lt;/td&gt; &lt;/tr&gt;</p><p>&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;24.54%&quot;&gt;&lt;p&gt;OpBasicInfo.csv&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;75.46000000000001%&quot;&gt;&lt;p&gt;算子基础信息，包含算子名称、block dim和耗时等信息，可参考OpBasicInfo（算子基础信息）。 &lt;/td&gt; &lt;/tr&gt;</p><p>&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;24.54%&quot;&gt;&lt;p&gt;visualize_data.bin&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;75.46000000000001%&quot;&gt;&lt;p&gt;算子基础信息、计算单元负载、热点函数和Roofline瓶颈分析等信息的可视化呈现文件。visualize_data.bin可通过MindStudio Insight工具进行可视化展示。 &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;24.54%&quot;&gt;&lt;p&gt;trace.json&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;75.46000000000001%&quot;&gt;&lt;p&gt;通算流水可视化呈现文件，Chrome浏览器具体请参考通算流水图。 &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><p>对于SIMT编程场景，只需遵循<a href="./../编译与运行/算子编译/AI-Core算子编译基本用法.html">AI Core SIMT编译</a>指导进行算子编译，生成可执行文件后，按照上述步骤2和步骤3使用msprof工具执行程序，以获取算子执行的性能数据。</p><h2 id="npu域仿真性能分析" tabindex="-1">NPU域仿真性能分析 <a class="header-anchor" href="#npu域仿真性能分析" aria-label="Permalink to &quot;NPU域仿真性能分析&quot;">​</a></h2><p>在非昇腾设备上，通过毕昇编译器仿真编译后生成可执行程序，可以通过msprof op simulator完成性能流水仿真。当前仅支持SIMD编程场景，SIMT编程场景不支持。</p><ul><li><p><strong>通过CMake方式仿真编译算子</strong></p><ul><li><p>灵活控制不同的target是否开启仿真编译。修改CMakeList，使用target_link_libraries与target_link_directories手动配置链接库与路径：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>find_package(ASC REQUIRED)</span></span>
<span class="line"><span>project(kernel_samples LANGUAGES ASC)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>add_executable(demo</span></span>
<span class="line"><span>    add_custom.asc</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>set_target_properties(demo PROPERTIES </span></span>
<span class="line"><span>    LINK_FLAGS &quot;-Wl,--disable-new-dtags&quot;  ## 由于仿真库会依赖当前目录的其他非链接的so，需要开启RPATH传递依赖目录</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>target_link_libraries(demo PRIVATE</span></span>
<span class="line"><span>    runtime_camodel npu_drv_camodel  ## 仿真编译需要链接的so</span></span>
<span class="line"><span>    m</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span></span></span>
<span class="line"><span># \${INSTALL_DIR}请替换为CANN软件安装后文件存储路径。以root用户安装为例，安装后文件默认存储路径为：/usr/local/Ascend/cann。</span></span>
<span class="line"><span>target_link_directories(demo PRIVATE</span></span>
<span class="line"><span>    \${INSTALL_DIR}/tools/simulator/dav_2201/lib  ##仿真库所在的目录，其中dav_2201目录名称与芯片版本相关 </span></span>
<span class="line"><span>)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>target_compile_options(demo PRIVATE</span></span>
<span class="line"><span>    $&lt;$&lt;COMPILE_LANGUAGE:ASC&gt;: --npu-arch=dav-2201&gt;</span></span>
<span class="line"><span>)</span></span></code></pre></div><p>其中仿真库所在目录与NPU架构版本号之间的关系如下，目录名使用<strong>下划线</strong>连接“dav”和架构版本号。</p><p>其中仿真编译所依赖的库介绍如下，开启仿真编译时，需要优先链接，确保优先使用仿真库的符号，防止出现运行时coredump等异常情况。</p><p><strong>表3 仿真编译依赖库介绍</strong></p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;45.97%&quot;&gt;&lt;p&gt;名称&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;54.03%&quot;&gt;&lt;p&gt;作用描述&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;45.97%&quot;&gt;&lt;p&gt;libruntime_camodel.so&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;54.03%&quot;&gt;&lt;p&gt;camodel仿真运行时库，负责NPU算子仿真环境的运行时功能支持。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;45.97%&quot;&gt;&lt;p&gt;libnpu_drv_camodel.so&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;54.03%&quot;&gt;&lt;p&gt;仿真驱动库，对真实的驱动接口打桩，模拟真实NPU驱动行为，提供硬件交付的接口仿真。&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p></li><li><p>通过向CMake传入变量CMAKE_ASC_RUN_MODE和CMAKE_ASC_ARCHITECTURES来统一开启仿真编译。命令示例如下：</p><p>sim表示开启仿真编译，dav-后为NPU架构版本号，请根据实际情况进行填写。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>cmake -B build -DCMAKE_ASC_RUN_MODE=sim -DCMAKE_ASC_ARCHITECTURES=dav-2201</span></span></code></pre></div><div class="note custom-block github-alert"><p class="custom-block-title">说明</p><p>使用命令行往CMake传入变量的方式全局生效，会对CMakeList中所有的target开启sim模式。</p></div></li></ul></li><li><p><strong>通过命令行方式仿真编译算子可执行程序</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 编译算子: bisheng  [算子源文件] -o [输出产物名称] --npu-arch=[NPU架构版本号]，--run-mode=sim</span></span>
<span class="line"><span>bisheng add_custom.asc -o add_custom --npu-arch=dav-2201 --run-mode=sim</span></span></code></pre></div></li><li><p><strong>性能流水仿真</strong></p><p>使用msprof op simulator并获取仿真数据。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>msprof op simulator ./add_custom --soc-version=Ascendxxxyy</span></span></code></pre></div><p>仿真数据说明</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>OPPROF_{timestamp}_XXX</span></span>
<span class="line"><span>├──dump                    # 原始的性能数据，用户无需关注</span></span>
<span class="line"><span>└──simulator               # 算子基础信息</span></span>
<span class="line"><span>   ├──core0.cubecore0</span></span>
<span class="line"><span>   ├──...</span></span>
<span class="line"><span>   ├──core23.cubecore0</span></span>
<span class="line"><span>   ├──trace.json           # Edge/Chrome Trace Viewer/Perfetto呈现文件</span></span>
<span class="line"><span>   └──visualize_data.bin   # MindStudio Insight呈现文件</span></span></code></pre></div></li></ul><p><strong>表4 msprof op simulator文件介绍</strong></p><table tabindex="0"><thead><tr><th>名称</th><th>说明</th></tr></thead><tbody><tr><td>dump文件夹</td><td>原始仿真生成的dump数据存放文件夹。</td></tr><tr><td>core*_code_exe.csv</td><td>代码行耗时，*代表0~n核，以便用户快速确定编写的代码中最耗时的部分，可参考代码行耗时数据文件。</td></tr><tr><td>core*_instr_exe.csv</td><td>代码指令详细信息，*代表0~n核，以便用户快速确定最耗时的指令，可参考代码指令信息文件。</td></tr><tr><td>visualize_data.bin</td><td>仿真流水图和仿真热点函数等信息可视化呈现文件。</td></tr><tr><td>trace.json</td><td>仿真指令流水图文件，包括每个核的子文件以及全部核的汇总文件，可参考指令流水图和内存通路吞吐率波形图。</td></tr></tbody></table><p>更多详细的信息可以参考<a href="https://hiascend.com/document/redirect/CannCommercialToolOpDev" target="_blank" rel="noreferrer">《算子开发工具用户指南》</a> 中的“算子调优 (msOpProf)”章节。</p>`,24)])])}const q=a(n,[["render",p]]);export{g as __pageData,q as default};
